Разная длина или лишний Character оставляют ненулевую частоту.

func merged(_ first: [Int], _ second: [Int]) -> [Int] {
    var a = 0, b = 0
    var result: [Int] = []
    while a < first.count && b < second.count {
        if first[a] <= second[b] {
            result.append(first[a])
            a += 1
        } else {
            result.append(second[b])
            b += 1
        }
    }
    result.append(contentsOf: first[a...])
    result.append(contentsOf: second[b...])
    return result
}
assert(merged([1, 4], [2, 4]) == [1, 2, 4, 4])
assert(merged([], []) == [])
assert(merged([1], []) == [1])

