func palindrome(_ text: String) -> Bool {
    let values = Array(text)
    var left = 0, right = values.count - 1
    while left < right {
        if values[left] != values[right] { return false }
        left += 1
        right -= 1
    }
    return true
}
assert(palindrome("топот"))
assert(palindrome("👨‍👩‍👧‍👦а👨‍👩‍👧‍👦"))
assert(palindrome(""))
assert(!palindrome("Топот"))

Не меняем нормализацию молча; граница защищает пустой вход.

func twoSum(_ values: [Int], target: Int) -> (Int, Int)? {
    var left = 0, right = values.count - 1
    while left < right {
        let sum = values[left] + values[right]
        if sum == target { return (left, right) }
        if sum < target { left += 1 } else { right -= 1 }
    }
    return nil
}
let pair = twoSum([1, 3, 4, 8], target: 7)
assert(pair?.0 == 1 && pair?.1 == 2)
assert(twoSum([3], target: 6) == nil)
assert(twoSum([], target: 6) == nil)

