Указатель записи не догоняет непрочитанную часть.

func uniquePrefix(_ values: inout [Int]) -> Int {
    guard !values.isEmpty else { return 0 }
    var write = 1
    for read in 1..<values.count where values[read] != values[write - 1] {
        values[write] = values[read]
        write += 1
    }
    return write
}
var values = [1, 1, 2, 3, 3]
let count = uniquePrefix(&values)
assert(Array(values.prefix(count)) == [1, 2, 3])
var empty: [Int] = []
assert(uniquePrefix(&empty) == 0)

Ответ — длина и префикс, размер storage не обязан измениться.

func longestDistinct(_ text: String) -> Int {
    let values = Array(text)
    var last: [Character: Int] = [:]
    var left = 0, best = 0
    for right in values.indices {
        if let previous = last[values[right]], previous >= left {
            left = previous + 1
        }
        last[values[right]] = right
        best = max(best, right - left + 1)
    }
    return best
}
assert(longestDistinct("abba") == 2)
assert(longestDistinct("👨‍👩‍👧‍👦а👨‍👩‍👧‍👦б") == 3)
assert(longestDistinct("") == 0)

left не двигается назад; повтор вне текущего окна не сужает его.

func balanced(_ text: String) -> Bool {
    let pairs: [Character: Character] = [")": "(", "]": "[", "}": "{"]
    var stack: [Character] = []
    for character in text {
        if "([{".contains(character) {
            stack.append(character)
        } else if let opening = pairs[character] {
            guard stack.popLast() == opening else { return false }
        } else { return false }
    }
    return stack.isEmpty
}
assert(balanced("([]){}"))
assert(!balanced("([)]"))
assert(!balanced("("))
assert(balanced(""))
assert(!balanced("a"))

