struct RecordSnapshot: Equatable {
    let id: Int
    let revision: Int
    let text: String
}
func applyUpdates(
    _ updates: [RecordSnapshot], local: [RecordSnapshot]
) -> [RecordSnapshot] {
    var index = Dictionary(uniqueKeysWithValues: local.map { ($0.id, $0) })
    for value in updates {
        if let old = index[value.id], old.revision >= value.revision {
            continue
        }
        index[value.id] = value
    }
    return index.values.sorted { $0.id < $1.id }
}
let original = RecordSnapshot(id: 1, revision: 2, text: "Новое")
let old = RecordSnapshot(id: 1, revision: 1, text: "Старое")
let extra = RecordSnapshot(id: 2, revision: 1, text: "Другое")
let result = applyUpdates([old, extra, extra], local: [original])
assert(result == [original, extra])

